import ast,importlib.metadata as meta

def size(p):
 text=p.read_text(encoding='utf-8-sig');tree=ast.parse(text);doc=set()
 for n in ast.walk(tree):
  if isinstance(n,(ast.Module,ast.ClassDef,ast.FunctionDef,ast.AsyncFunctionDef)) and n.body and isinstance(n.body[0],ast.Expr) and isinstance(n.body[0].value,ast.Constant) and isinstance(n.body[0].value.value,str):doc.update(range(n.body[0].lineno,n.body[0].end_lineno+1))
 return {'physical_lines':len(text.splitlines()),'meaningful_lines':sum(bool(line.strip()) and not line.lstrip().startswith('#') and i not in doc for i,line in enumerate(text.splitlines(),1)),'AST_statements':sum(isinstance(n,ast.stmt) and not(isinstance(n,ast.Expr) and isinstance(n.value,ast.Constant) and isinstance(n.value.value,str)) for n in ast.walk(tree)),'bytes':len(p.read_bytes()),'functions_and_methods':sum(isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) for n in ast.walk(tree))}
